const current=talk[talkIdx];const artAnimal=s?.animals.find(a=>a.id===selectedAnimal);const region=regions.find(r=>r.id===selectedRegion)!;const canAuto=!!s&&s.power>=region.power+(selectedGear.includes('scanner')?8:0);const canManual=!!s&&selectedGear.includes('flashlight')&&s.flashlight>=20;const live=s?.animals.filter(a=>a.alive)||[];const nextIncident=s?.pendingIncident?incidentDefs[s.pendingIncident]:null;
